def verify(result):
    cand = result.get('correct', '') if isinstance(result, dict) else str(result)
    a = result['vars']['a']
    b = result['vars']['b']
    target = f'{a} & 0 \\\\ 0 & {b}'
    return (target in cand) and ('antidiagonal' not in cand) and ('invertida' not in cand) and ('unos' not in cand) and ('dobles' not in cand) and ('unitaria' not in cand)

def verify(result):
    v = result['vars']
    return v['a'] > 0 and v['b'] > 0 and v['tr_val'] < 0 and v['det_val'] > 0 and len([o for o in result['options'] if o['is_correct']]) >= 2

def verify(result):
    cand = result.get('correct', '') if isinstance(result, dict) else str(result)
    a = result['vars']['a']
    diff = result['vars']['diff']
    target = f'-{a} & 0 \\\\ 0 & {diff}'
    return (target in cand) and ('origen' not in cand) and ('antidiagonal' not in cand) and ('cruzados' not in cand) and ('identidad' not in cand)
